import{_ as t,o,c as a,ag as r}from"./chunks/framework.BuUvxvtQ.js";const p=JSON.parse('{"title":"Dashboard & Closet","description":"","frontmatter":{},"headers":[],"relativePath":"web-app/dashboard.md","filePath":"web-app/dashboard.md"}'),n={name:"web-app/dashboard.md"};function s(i,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="dashboard-closet" tabindex="-1">Dashboard &amp; Closet <a class="header-anchor" href="#dashboard-closet" aria-label="Permalink to &quot;Dashboard &amp; Closet&quot;">​</a></h1><p>The dashboard is the heart of Sky Style — live weather, your preferences, and an AI outfit recommendation in one place.</p><h2 id="dashboard-layout" tabindex="-1">Dashboard layout <a class="header-anchor" href="#dashboard-layout" aria-label="Permalink to &quot;Dashboard layout&quot;">​</a></h2><p>The dashboard is split into a <strong>weather panel</strong> and a <strong>settings panel</strong>. The split is adjustable in <a href="./settings.html#layout-and-spacing">Settings → Layout &amp; spacing</a>:</p><ul><li><strong>Symmetrical Split</strong> — both panels equal width.</li><li><strong>Large Weather</strong> (default) — weather panel is wider.</li><li><strong>Large Settings</strong> — settings panel is wider.</li></ul><p>When <strong>Custom Column Spacing</strong> is on, hover between the two panels to reveal a drag handle and resize them freely. The ratio is saved automatically.</p><h2 id="location" tabindex="-1">Location <a class="header-anchor" href="#location" aria-label="Permalink to &quot;Location&quot;">​</a></h2><p>Choose how Sky Style locates you:</p><ul><li><strong>GPS</strong> — permit browser location access for the most accurate local weather.</li><li><strong>Manual</strong> — type any city or coordinates.</li></ul><p>Your location consent is controlled in <a href="./settings.html#preferences">Settings → Preferences</a>.</p><h2 id="recommendation-modes" tabindex="-1">Recommendation modes <a class="header-anchor" href="#recommendation-modes" aria-label="Permalink to &quot;Recommendation modes&quot;">​</a></h2><p>Each recommendation can run at one of four complexity levels, selected in the Weather Planning panel:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td>Simple</td><td>A concise outfit suggestion.</td></tr><tr><td>Simple+</td><td>Slightly more detail.</td></tr><tr><td>Advanced</td><td>Deeper reasoning and options.</td></tr><tr><td>Pro</td><td>The most thorough recommendation.</td></tr></tbody></table><p>Your default mode is configurable in <a href="./settings.html#dashboard-behaviour">Settings → Dashboard behaviour</a>.</p><h2 id="follow-up-questions" tabindex="-1">Follow-up questions <a class="header-anchor" href="#follow-up-questions" aria-label="Permalink to &quot;Follow-up questions&quot;">​</a></h2><p>After a recommendation, ask follow-ups like &quot;should I bring an umbrella?&quot; or &quot;what if I need formal shoes?&quot;. Follow-ups run in one of two modes:</p><ul><li><strong>Replace mode</strong> (default) — each follow-up overwrites the current outfit suggestion.</li><li><strong>Chat mode</strong> — follow-ups append below, keeping a running conversation history.</li></ul><p>Switch modes in <a href="./settings.html#dashboard-behaviour">Settings → Dashboard behaviour</a>.</p><div class="tip custom-block"><p class="custom-block-title">Daily limits</p><p>Follow-ups are limited per day based on your plan (Free: 40/day, Pro: 400/day). When you hit the limit, the dashboard shows your usage and the limit resets at midnight UTC.</p></div><h2 id="weather-planning-panel" tabindex="-1">Weather Planning panel <a class="header-anchor" href="#weather-planning-panel" aria-label="Permalink to &quot;Weather Planning panel&quot;">​</a></h2><p>The Weather Planning panel on the dashboard lets you control how a recommendation is generated:</p><ul><li><strong>Recommendation mode</strong> — Simple, Simple+, Advanced, or Pro (see <a href="#recommendation-modes">Recommendation modes</a> above).</li><li><strong>Source picker</strong> (Pro) — choose which built-in weather source to use for this recommendation. Free users get 4 source picks/day; Pro is unlimited. See <a href="./how-it-works.html#weather-sources">How It Works → Weather sources</a>.</li><li><strong>Hourly forecast</strong> — when the selected source provides it, an hourly breakdown (time, temperature, description, rain chance, wind speed) is shown so you can plan around changing conditions.</li><li><strong>Accuracy</strong> — for BOM (Australia) data, the panel shows the accuracy score based on distance to the nearest station (see <a href="./how-it-works.html#accuracy-score">Accuracy score</a>).</li></ul><p>The panel&#39;s default state (always open, closed, or disabled) is configurable in <a href="./settings.html#dashboard-behaviour">Settings → Dashboard behaviour</a>.</p><h2 id="model-switching" tabindex="-1">Model switching <a class="header-anchor" href="#model-switching" aria-label="Permalink to &quot;Model switching&quot;">​</a></h2><p>You can change which AI model generates your recommendation. <strong>Model switches are a separate daily counter</strong> from AI uses:</p><table tabindex="0"><thead><tr><th>Plan</th><th>Model switches</th></tr></thead><tbody><tr><td>Free</td><td>2/day</td></tr><tr><td>Pro</td><td>Unlimited</td></tr><tr><td>Dev</td><td>Unlimited</td></tr></tbody></table><p>Switching counts even if the previous model was unavailable. See <a href="./how-it-works.html#ai-models">How It Works → AI models</a> for the full model priority list.</p><h2 id="bring-your-own-key-pro-dev" tabindex="-1">Bring Your Own Key (Pro &amp; Dev) <a class="header-anchor" href="#bring-your-own-key-pro-dev" aria-label="Permalink to &quot;Bring Your Own Key (Pro &amp; Dev)&quot;">​</a></h2><p>Pro and Dev users can supply their own AI provider key so recommendations are billed to their own account.</p><ul><li><strong>Supported providers</strong>: OpenAI, Google Gemini, and Mistral AI.</li><li>Keys are stored <strong>only in your browser</strong> and are never sent to Sky Style servers except for the single AI request.</li><li>A <strong>custom prompt</strong> can replace the default Sky Style prompt — it must include JSON output instructions and is stored locally only.</li></ul><div class="tip custom-block"><p class="custom-block-title">BYOK is optional</p><p>Without a BYOK key, Sky Style uses its own AI provider according to your plan tier. See <a href="./account-and-support.html#plans">Plans</a>.</p></div><h2 id="closet" tabindex="-1">Closet <a class="header-anchor" href="#closet" aria-label="Permalink to &quot;Closet&quot;">​</a></h2><p>The <strong>Closet</strong> page (<code>/closet</code>) holds the clothes you own so the AI can tailor recommendations to your actual wardrobe.</p><ul><li>Items are returned in the order you added them.</li><li>Closet usage is limited per day on the Free plan (4 uses/day) and unlimited on Pro/Dev.</li><li>The closet panel can be expanded directly from the dashboard or managed on its own page.</li></ul>',34)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
